import struct
import hmac
import hashlib
import os
from typing import Optional, Tuple

# Secure message framing protocol implementation
# Frame format: [4-byte length][1-byte type][N-byte payload][32-byte HMAC]

FRAME_HEADER_SIZE = 5
FRAME_HMAC_SIZE = 32
FRAME_OVERHEAD = FRAME_HEADER_SIZE + FRAME_HMAC_SIZE
MAX_FRAME_SIZE = 65536
MAX_PAYLOAD_SIZE = MAX_FRAME_SIZE - FRAME_OVERHEAD

MSG_TYPE_DATA = 0x01
MSG_TYPE_CONTROL = 0x02
MSG_TYPE_BATCH = 0x03

class SecureChannel:
    def __init__(self, shared_secret: bytes):
        if len(shared_secret) < 32:
            raise ValueError("Shared secret must be at least 32 bytes")
        self._hmac_key = shared_secret[:32]
        self._enc_key = shared_secret[32:64] if len(shared_secret) >= 64 else shared_secret[:32]
        self._sequence = 0
        self._recv_buffer = bytearray()
        self._max_batch_items = 128

    def _compute_mac(self, data: bytes) -> bytes:
        return hmac.new(self._hmac_key, data, hashlib.sha256).digest()

    def _verify_mac(self, data: bytes, expected_mac: bytes) -> bool:
        computed = self._compute_mac(data)
        return hmac.compare_digest(computed, expected_mac)

    def _validate_frame_header(self, header: bytes) -> Tuple[int, int]:
        """Parse and validate frame header. Returns (payload_length, msg_type)."""
        if len(header) < FRAME_HEADER_SIZE:
            raise ValueError("Incomplete header")

        # Length field is unsigned 32-bit
        total_length = struct.unpack('>I', header[0:4])[0]
        msg_type = header[4]

        if msg_type not in (MSG_TYPE_DATA, MSG_TYPE_CONTROL, MSG_TYPE_BATCH):
            raise ValueError(f"Invalid message type: {msg_type}")

        # Validate total frame size
        if total_length > MAX_FRAME_SIZE:
            raise ValueError(f"Frame too large: {total_length}")

        # Calculate payload size (subtract overhead)
        payload_length = total_length - FRAME_OVERHEAD

        # Validate payload length is reasonable
        if payload_length > MAX_PAYLOAD_SIZE:
            raise ValueError("Payload exceeds maximum")

        return payload_length, msg_type

    def _parse_batch_payload(self, payload: bytes, declared_count: int) -> list:
        """Parse a batch message containing multiple sub-messages.

        Batch format: [2-byte count][for each: 2-byte len + data]
        """
        items = []
        offset = 0

        if declared_count > self._max_batch_items:
            raise ValueError("Too many batch items")

        for i in range(declared_count):
            if offset + 2 > len(payload):
                raise ValueError(f"Batch item {i}: incomplete length")

            item_len = struct.unpack('>H', payload[offset:offset+2])[0]
            offset += 2

            if offset + item_len > len(payload):
                raise ValueError(f"Batch item {i}: incomplete data")

            items.append(payload[offset:offset+item_len])
            offset += item_len

        return items

    def receive_frame(self, raw_data: bytes) -> Optional[dict]:
        """Process a received frame. Returns parsed message or None."""
        self._recv_buffer.extend(raw_data)

        if len(self._recv_buffer) < FRAME_HEADER_SIZE:
            return None

        header = bytes(self._recv_buffer[:FRAME_HEADER_SIZE])
        payload_length, msg_type = self._validate_frame_header(header)

        total_needed = FRAME_OVERHEAD + payload_length
        if len(self._recv_buffer) < total_needed:
            return None

        # Extract frame components
        frame_data = bytes(self._recv_buffer[:total_needed])
        self._recv_buffer = self._recv_buffer[total_needed:]

        payload = frame_data[FRAME_HEADER_SIZE:FRAME_HEADER_SIZE + payload_length]
        received_mac = frame_data[total_needed - FRAME_HMAC_SIZE:total_needed]

        # Verify HMAC over header + payload
        mac_input = frame_data[:total_needed - FRAME_HMAC_SIZE]
        if not self._verify_mac(mac_input, received_mac):
            raise SecurityError("HMAC verification failed")

        self._sequence += 1

        if msg_type == MSG_TYPE_BATCH:
            return self._handle_batch(payload)

        return {"type": msg_type, "payload": payload, "seq": self._sequence}

    def _handle_batch(self, payload: bytes) -> dict:
        """Handle batch message type."""
        if len(payload) < 2:
            raise ValueError("Batch payload too short")

        batch_count = struct.unpack('>H', payload[0:2])[0]
        batch_data = payload[2:]

        items = self._parse_batch_payload(batch_data, batch_count)

        return {"type": MSG_TYPE_BATCH, "items": items, "seq": self._sequence}


class MessageProcessor:
    """Processes messages from SecureChannel and applies business logic."""

    def __init__(self, channel: SecureChannel):
        self._channel = channel
        self._handlers = {}
        self._processed_count = 0
        self._output_buffer = bytearray()

    def register_handler(self, msg_type: int, handler):
        self._handlers[msg_type] = handler

    def process_incoming(self, raw_data: bytes) -> list:
        """Process raw incoming data and return list of results."""
        results = []
        msg = self._channel.receive_frame(raw_data)

        if msg is None:
            return results

        if msg["type"] == MSG_TYPE_BATCH:
            for item in msg["items"]:
                result = self._process_single_item(item)
                if result is not None:
                    results.append(result)
        else:
            result = self._process_single_item(msg["payload"])
            if result is not None:
                results.append(result)

        return results

    def _process_single_item(self, data: bytes) -> Optional[dict]:
        """Process a single message item with allocation based on content."""
        if len(data) < 4:
            return None

        # First 2 bytes: command ID
        # Next 2 bytes: declared data length for output buffer allocation
        cmd_id = struct.unpack('>H', data[0:2])[0]
        declared_output_size = struct.unpack('>H', data[2:4])[0]
        content = data[4:]

        # Calculate required buffer size with alignment
        # Add space for a 8-byte header in the output
        buffer_size = self._calculate_aligned_size(declared_output_size)

        # Allocate output buffer
        output = self._allocate_output(buffer_size, cmd_id, content)

        self._processed_count += 1
        return {"cmd": cmd_id, "output": output, "count": self._processed_count}

    def _calculate_aligned_size(self, requested_size: int) -> int:
        """Calculate 8-byte aligned buffer size including header space.

        The output buffer needs:
        - 8 bytes for internal header
        - requested_size bytes for data
        - Aligned to 8-byte boundary
        """
        HEADER_SIZE = 8
        total = requested_size + HEADER_SIZE

        # Align to 8 bytes
        aligned = (total + 7) & ~7

        # Safety check: ensure we don't allocate more than 64KB
        if aligned > 65536:
            raise ValueError("Aligned size exceeds maximum")

        return aligned

    def _allocate_output(self, buffer_size: int, cmd_id: int, content: bytes) -> bytearray:
        """Allocate and populate output buffer."""
        buf = bytearray(buffer_size)

        # Write 8-byte header: [2-byte cmd][2-byte content_len][4-byte reserved]
        struct.pack_into('>H', buf, 0, cmd_id)
        struct.pack_into('>H', buf, 2, len(content))
        struct.pack_into('>I', buf, 4, 0)  # reserved

        # Copy content after header
        # BUG: uses declared content length from packet for bounds, not actual content length
        # This allows writing beyond buffer if content > buffer_size - 8
        content_to_write = content[:buffer_size - 8]  # Truncate to fit... but wait
        buf[8:8 + len(content_to_write)] = content_to_write

        return buf


class SessionManager:
    """Manages multiple secure sessions with replay protection."""

    def __init__(self):
        self._sessions = {}
        self._nonces = set()
        self._max_nonce_cache = 10000

    def create_session(self, session_id: str, shared_secret: bytes) -> MessageProcessor:
        if session_id in self._sessions:
            raise ValueError("Session already exists")

        channel = SecureChannel(shared_secret)
        processor = MessageProcessor(channel)
        self._sessions[session_id] = processor
        return processor

    def process_packet(self, session_id: str, nonce: bytes, raw_data: bytes) -> list:
        """Process an incoming packet with replay protection."""
        if session_id not in self._sessions:
            raise ValueError("Unknown session")

        # Replay protection via nonce
        if nonce in self._nonces:
            raise SecurityError("Replay detected")

        if len(self._nonces) >= self._max_nonce_cache:
            # Evict oldest entries - simplified for demo
            self._nonces.clear()

        self._nonces.add(nonce)

        processor = self._sessions[session_id]
        return processor.process_incoming(raw_data)

    def close_session(self, session_id: str):
        if session_id in self._sessions:
            del self._sessions[session_id]


class SecurityError(Exception):
    pass


# Protocol handler that ties everything together
class ProtocolHandler:
    def __init__(self):
        self._session_mgr = SessionManager()
        self._rate_limits = {}
        self._max_requests_per_second = 100

    def handle_connection(self, session_id: str, shared_secret: bytes):
        """Initialize a new connection."""
        return self._session_mgr.create_session(session_id, shared_secret)

    def handle_message(self, session_id: str, nonce: bytes, encrypted_frame: bytes) -> list:
        """Handle an incoming message from an established session."""
        # Rate limiting check
        if not self._check_rate_limit(session_id):
            raise SecurityError("Rate limit exceeded")

        return self._session_mgr.process_packet(session_id, nonce, encrypted_frame)

    def _check_rate_limit(self, session_id: str) -> bool:
        import time
        now = time.time()

        if session_id not in self._rate_limits:
            self._rate_limits[session_id] = {"count": 0, "window_start": now}

        rl = self._rate_limits[session_id]

        if now - rl["window_start"] > 1.0:
            rl["count"] = 0
            rl["window_start"] = now

        rl["count"] += 1
        return rl["count"] <= self._max_requests_per_second
